+			}
+			r, _, _ := j.lookup(l.Instance)
+			name := resourceRecordName(l.Instance)
+			switch change {
+			case "version":
+				r.Version = 4
+			case "source":
+				r.Prepared.Source = "prepared-not-a-uuid"
+			case "target":
+				r.Prepared.Target = "../guest"
